using System;using System.IO;using System.Linq;using System.Drawing;using System.Threading;using System.Windows.Forms;using System.Diagnostics;using System.Collections.Generic;
namespace GearLab {
 public partial class MainForm {
  internal void TransmissionRegression60(string folder){animation.Stop();var checks=new List<string>();var timings=new List<object>();int workers=CADKernel.StartedWorkers;var menu=MainMenuStrip;var button=calculate;Action<bool,string> c=(ok,msg)=>{if(!ok)throw new Exception(msg);checks.Add(msg);};for(int k=0;k<13;k++){SetHostedKind(k);Application.DoEvents();c(p.Kind==k&&result.Valid&&result.Model.Valid,"family "+k+": "+string.Join(";",result.Errors.Concat(result.Model.Errors)));var clock=Stopwatch.StartNew();ShowFullModel();var scene=canvas.Viewer.Scene;while(!scene.Ready&&scene.Error==null&&clock.Elapsed.TotalSeconds<15){Application.DoEvents();Thread.Sleep(5);}c(scene.Ready,"3D scene "+k+": "+scene.Error);c(scene.TriangleCount>100&&scene.Nodes.Count==result.Model.Parts.Count,"real geometry "+k);c(ReferenceEquals(menu,MainMenuStrip)&&ReferenceEquals(button,calculate),"shared UI "+k);c(CADKernel.StartedWorkers==workers,"no native worker "+k);int meshes=SceneMesher.Builds;for(int j=0;j<20;j++)scene.UpdatePose(j*.1);c(SceneMesher.Builds==meshes,"animation no remesh "+k);timings.Add(new{Kind=k,ReadyMilliseconds=clock.Elapsed.TotalMilliseconds,Triangles=scene.TriangleCount});if(k>=5){var cached=result.Model;numbers["InputTorque"].Commit(.4m);calculate.PerformClick();c(ReferenceEquals(cached,result.Model),"torque keeps geometry "+k);c(result.TransmissionMotions.Count>0,"motion metadata survives cached model "+k);if(k==5||k==8||k==11||k==12){scene.SavePng(Path.Combine(folder,"type-"+k+"-scene.png"),1200,800);ShowModelView(0);Application.DoEvents();using(var b=new Bitmap(Width,Height)){DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(folder,"type-"+k+"-ui.png"));}}}}
   File.WriteAllText(Path.Combine(folder,"ui60-results.json"),CADDocument.Serializer().Serialize(new{Checks=checks,Previews=timings,NativeWorkers=CADKernel.StartedWorkers-workers}));
  }
 }
 public static class TransmissionUi60Tests {
  public static int Run(string folder){Directory.CreateDirectory(folder);try{var reducers=new ReducerWorkspaceForm();using(var shell=new WorkspaceShell(reducers)){shell.Show();Application.DoEvents();reducers.MainView.TransmissionRegression60(folder);if(shell.Pages.TabCount!=1)throw new Exception("Duplicate reducer tabs");shell.Navigate("train");Application.DoEvents();if(shell.Pages.TabCount!=2||!(shell.Pages.SelectedTab.Tag is TrainDesignerForm))throw new Exception("Train editor did not open in workspace");shell.ApproveTestClose();shell.Close();}string oldError=Path.Combine(folder,"ui60-error.txt");if(File.Exists(oldError))File.Move(oldError,Path.Combine(folder,"ui60-first-attempt-"+DateTime.Now.Ticks+".txt"));return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"ui60-error.txt"),ex.ToString());return 1;}}
 }
}
